"""Implementation report, complete attempt accounting, and unfulfilled evidence gates."""
from pathlib import Path
from collections import Counter
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports/v3';OUT.mkdir(parents=True,exist_ok=True)
METHODS=['v2_guarded','v3_no_repair','v3_constrained']
def read(name):return json.loads((ROOT/'results/v3'/name).read_text())
def summary(rows,method):
    r=[r for r in rows if r['method']==method]
    return {'attempts':len(r),'accepted_reference_passed':sum(x['status']=='accepted' and x['reference_passed'] for x in r),
        'accepted_reference_failed':sum(x['status']=='accepted' and not x['reference_passed'] for x in r),'review':sum(x['status']=='needs_review' for x in r),
        'rejected':sum(x['status']=='rejected' for x in r),'execution_failed':sum(x['status']=='execution_failed' for x in r)}

def main():
    studies={k:read(k+'/index.json') for k in ['development','development_corrected','holdout']}
    assert all(r['status']=='completed' for r in studies.values());totals={k:{m:summary(d['cases'],m) for m in METHODS} for k,d in studies.items()}
    test=read('test_summary.json');workflow=read('workflows/index.json');external=read('external/index.json');exact=read('exact_comparison/index.json');references=read('reference_audit/index.json');holdout=totals['holdout']['v3_constrained']
    unique={r['input_sha256'] for d in studies.values() for r in d['cases'] if r.get('input_sha256')}
    results={'status':'research_implementation_evaluated_not_release_qualified','main_attempt_records':sum(d['attempts'] for d in studies.values()),'unique_main_ifc_hashes':len(unique),
        'study_summaries':totals,'fresh_holdout_inputs':160,'accepted_holdout_counterexamples':[r for r in studies['holdout']['cases'] if r['method']=='v3_constrained' and r['status']=='accepted' and not r['reference_passed']],
        'reference_erratum':{'historical_cases':8,'pass_with_corrected_reference':sum(r['corrected_metrics']['all_guards_passed'] for r in references['cases']),'historical_recheck':read('historical_recheck/index.json')},
        'native_exact_intersection_logging_audit':read('exact_intersection_check/index.json'),'measurement_exception_recovery':read('measurement_recovery_equivalence.json'),'native_exact_logging_audit':read('exact_logging_check/index.json'),'native_exact_comparison':exact,'workflows':workflow,'external_initial':external,'external_schema_followup':read('schema_adapter/index.json'),'external_bounded_followup':read('bounded_adapter/index.json'),
        'tests':test,'browser_checks':16,'figures':12,'independent_semantic_regions':0,'verified_torino_ifc_survey_pairs':0,'native_backend_promoted':False,'supported_converter_release_promoted':False,
        'evaluation_limits':['Connection-aware targets differ from source-only baseline capabilities','Initial development reference was corrected before final holdout','Post-evaluation diagnostics did not retune frozen holdout decisions','Finite samples and topology indicators are not formal fidelity certificates','No independent scan registration or semantic reference scores']}
    (OUT/'Results_Summary.json').write_text(json.dumps(results,indent=2),encoding='utf-8')
    rows=[]
    for study,d in totals.items():
        for method,r in d.items():rows.append('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in [study.replace('_',' '),method.replace('_',' '),r['attempts'],r['accepted_reference_passed'],r['accepted_reference_failed'],r['review'],r['rejected'],r['execution_failed']])+'</tr>')
    figures=json.loads((OUT/'figure_index.json').read_text())['figures']
    style='''*{box-sizing:border-box}body{margin:0;background:#f7f6f1;color:#243b3d;font:20px/1.5 "Palatino Linotype",Palatino,serif}article{max-width:1400px;margin:auto;padding:55px}h1{font-size:57px;line-height:1.1;font-weight:400}h2{font-size:33px;font-weight:400;margin-top:40px}a{color:#427263}p{max-width:1200px}small{color:#687b7a}.lead{font-size:25px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;margin:30px 0}.metrics div{border-top:2px solid #729183;padding-top:12px}.metrics strong{font-size:39px;font-weight:400;display:block}.note{border-left:4px solid #ad7458;background:#f0e7db;padding:16px 22px}.erratum{border-left:4px solid #47786a;background:#e8eee7;padding:14px 22px}table{border-collapse:collapse;width:100%;font-size:17px}th,td{padding:11px;text-align:left;border-bottom:1px solid #d2dbd4}th{background:#e5ece5}figure{margin:35px 0}figure img{display:block;width:100%;height:auto}figcaption{font-size:16px;color:#687b7a}.links{font-size:18px}@media screen and(max-width:800px){article{padding:22px}.metrics{grid-template-columns:1fr 1fr}h1{font-size:40px}.table{overflow:auto}}@media print{@page{size:400mm 250mm;margin:0}body{background:white}article{margin:0;padding:0;max-width:none}.cover,.methods,.results{height:250mm;padding:16mm 23mm;page-break-after:always;overflow:hidden}.cover{font-size:18px;line-height:1.35}.cover h1{font-size:44px;line-height:1.08;margin:16px 0}.cover p{font-size:20px;line-height:1.35;margin:12px 0}.cover .metrics{margin:25px 0;font-size:17px}.cover .metrics strong{font-size:36px}.methods p,.results p{font-size:18px;line-height:1.35;margin:12px 0;max-width:none}.methods h2,.results h2{margin:10px 0;font-size:31px}.results td,.results th{padding:8px;font-size:16px}figure{margin:0;width:400mm;height:250mm;page-break-after:always}figure img{width:400mm;height:250mm}figcaption,.screen-only{display:none}.last{page-break-after:auto}}'''
    body=f'''<section class="cover"><small>IFC → CITYGML / V3 IMPLEMENTATION AND EVIDENCE / 3 NOVEMBER 2026</small><h1>Geometry, intent,<br>and a record of every decision.</h1><p class="lead">An implemented research platform for constrained source-interface repairs, explicit abstention, query-aware generalisation and revision consistency.</p><div class="metrics"><div><strong>960</strong>main attempt records</div><div><strong>160</strong>fresh holdout inputs</div><div><strong>{test['unique_passed_tests']}</strong>distinct tests passed</div><div><strong>12</strong>new Palatino figures</div></div><p class="links"><a href="Geometry_and_Review.html">Geometry and independent-review viewer</a> · <a href="../../docs/V3_IMPLEMENTATION_GUIDE.md">Code and reproduction guide</a> · <a href="Results_Summary.json">Exact result summary</a></p><div class="note"><strong>Research decision: remain experimental.</strong> V3 accepts 115/160 holdout inputs: 111 pass every registered reference check; four accepted outputs fail checks. Eleven require review, 33 are rejected and one has an execution/measurement failure. External building qualification and independent semantic/local reference evidence remain insufficient.</div><div class="erratum"><strong>Reference correction:</strong> five of the eight historical V2 failures were caused by the analytical reference construction. Three persist; V3 routes those historical cases to review. Original evidence remains preserved.</div><p>The implementation adds an exact CGAL comparison, artifact-scoped review, source-linked evidence, bounded source eligibility and validated revision reuse. These capabilities are distinguished from formal geometry guarantees and production qualification.</p></section>'''
    body+='''<section class="methods"><h2>Methodology implemented</h2><p><strong>Representation and evidence.</strong> The core target is selected building material in engineering metres. Source Body selection, omissions, units and composed placements are retained. Explicit IFC relationships remain distinct from floating-point geometric hypotheses. Logical-only connections do not mandate a physical join. Supported interface planes are independently transformed from product-local coordinates and checked for consistency, opposed supports and overlap.</p><p><strong>Bounded candidate construction.</strong> Unquantised and source-oriented conditioned unions are evaluated with and without justified plane projections. Every edit has a displacement record and must fit the policy budget while protecting unasserted source separations. A conservative interaction index prunes pairs outside the declared influence range. Seventeen-digit CityGML coordinates must reconstruct the same binary output mesh coordinates.</p><p><strong>Decision and evaluation.</strong> Schema, surface/solid diagnostics, source correspondence and unresolved evidence determine operational status. Analytical references are consulted only afterwards. The 160-input holdout covers ordinary and tilted geometry, faceted re-encoding, logical/geometric/conflicting connections, real gaps and separate buildings sharing a wall. All attempts remain in the denominator. Source-only and connection-aware tasks are identified separately.</p><p><strong>Reference audit.</strong> The independent cell-boundary constructor was corrected to build unscaled arrangements before a single scale/rigid transform. Party-wall targets retain each building’s interface. Development versions and their matching code are archived. Historical rechecks and post-evaluation error localisation are not relabelled as independent validation.</p><p><strong>Supporting workflows.</strong> Query candidates are filtered by measured boundary, volume, component/Euler and protected-void checks, then compared on a Pareto frontier. Revision updates reuse qualified building results through geometry/policy/relationship fingerprints and conservative dependency invalidation; full rebuilding verifies canonical geometry and lineage. Reference imports require the exact input/output hashes. Scenario exposure fixes hazard identity and source feature IDs, separating representation changes from declared placement scenarios.</p><p><strong>Exactness and limits.</strong> A compiled CGAL rational comparator operates on represented input doubles with exact-limb logging audited separately from its initial approximate quotient-text logs. Double serialization is checked separately. It cannot establish physical intent or undo IFC tessellation error. Finite samples, shell indicators and interface diagnostics are not formal global certificates. A separate telemetry recovery preserves the measurement-exception ledger and reproduces its original GML bytes. The frozen converter release remains separate.</p></section>'''
    body+='<section class="results"><h2>Every main attempt is accounted for</h2><p>Accepted + passed means operational acceptance and all registered reference checks. The initial and corrected development runs repeat the same physical IFC inputs with a changed reference; the combined suites contain '+str(len(unique))+' distinct main input hashes, not 320 independent buildings.</p><table><thead><tr><th>Study</th><th>Method</th><th>Attempts</th><th>Accepted + passed</th><th>Accepted failures</th><th>Review</th><th>Rejected</th><th>Execution failed</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table><p><strong>Task eligibility:</strong> V2 does not implement the declared connection-plane repair targets. Aggregate challenge counts therefore do not prove numerical superiority. V3 still has four accepted holdout reference failures and one execution failure; neither is hidden by review/rejection totals.</p><p><strong>Other completed checks:</strong> six of seven native exact unions complete; all five revision states match full rebuilding; the cylinder query selects 56 triangles instead of 792; the courtyard block fails protected-void/topology checks. Five new IFC/scan filename pairings are acquired and audited, with no independent registration accuracy inferred.</p></section>'
    body+='<section>'+''.join(f'<figure><img src="figures/{f}.svg" alt="{f.replace("_"," ")}"><figcaption><a href="figures/{f}.svg">Editable SVG</a> · <a href="figures/{f}.png">3200×2000 PNG</a></figcaption></figure>' for f in figures)+'</section>'
    body+='''<section class="methods last"><h2>Qualification, prior work and remaining evidence</h2><p>The new <a href="https://zenodo.org/records/23808860">SUM4Re V2 subset</a> contributes five openly licensed IFCs and five HL2 scans. Publisher checksums and CC BY 4.0 attribution are retained. The public corpus now contains 31 distinct IFC hashes. Related sites and source pipelines are not automatically independent projects. The initial trials produce three timeouts and two unsupported outcomes. The bounded development follow-up rejects three and times out on two; none qualifies a strict material-union output.</p><p>The experimental IFC4X3 building adapter retains map metadata without applying it and rejects excessive source complexity. It does not qualify infrastructure alignments, linear placements or all building geometry. The resource guard prevents the observed unbounded convex-matrix allocation but cannot guarantee that SDK tessellation or subsequent processing stays within every resource limit.</p><p>Existing <a href="https://doc.cgal.org/6.2/PMP_Boolean_operations/index.html">CGAL Boolean methods</a> supply the exact-computation comparison. <a href="https://www.mdpi.com/2220-9964/15/11/483">Current graph-based conversion research</a> already examines traceability and interpretive decisions. Those are prior capabilities, not claimed inventions here. The present experiment concerns constrained interface edits, explicit abstention, source/serialization accounting and task/revision consistency; broader novelty and external generality remain to be established.</p><p>Independent semantic review is still absent. The browser and CSV workflow implement artifact-scoped review and disagreement evaluation, but neither creates independent labels. Scan registration and physical reference independence remain unverified. No genuine Torino IFC/survey-control pair is claimed; existing official Torino context remains a separate contextual result. No flood depth, damage or probability is inferred from the synthetic fixed-hazard demonstration.</p><p>Release promotion is withheld because of accepted counterexamples, external applicability failures and missing independent reference evidence. The implementation and twelve measured figures are delivered with reproducible scripts, protocols, snapshots and retained negative outcomes. <a href="../../docs/ADVANCED_EXTENSION_V3_EXECUTION.json">Work-package status</a> distinguishes software completion from scientific qualification.</p><p class="screen-only"><a href="../../docs/V3_IMPLEMENTATION_GUIDE.md">Open the full implementation and reproduction guide</a>.</p></section>'''
    (OUT/'Research_Report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>IFC to CityGML V3 — Implemented methods and evidence</title><style>'+style+'</style><article>'+body+'</article></html>',encoding='utf-8')
    statuses={
        'V3-01':('implemented','results/v3/diagnosis/index.json; results/v3/reference_audit/index.json; results/v3/historical_recheck/index.json'),
        'V3-02':('primary_source_positioning_recorded_novelty_claim_unqualified','docs/V3_IMPLEMENTATION_GUIDE.md'),
        'V3-03':('implemented_compiled_and_evaluated_with_timeout','tools/v3_native/build/BUILD_MANIFEST.json; results/v3/exact_comparison/index.json'),
        'V3-04':('implemented_plane_scope_other_geometry_abstains','research/ifc_citygml_v3/connections.py'),
        'V3-05':('bounded_checks_and_diagnostics_implemented_no_global_certificate','research/ifc_citygml_v3/checks.py; research/ifc_citygml_v3/diagnostics.py'),
        'V3-06':('implemented_experimental_accepted_counterexamples_remain','results/v3/holdout/index.json'),
        'V3-07':('implemented_fresh_mechanism_holdout_now_consumed','data/derived/v3/holdout/manifest.json'),
        'V3-08':('acquired_and_audited_reference_independence_unverified','data/raw/v3_sum4re/source_manifest.json; results/v3/scan_reference_audit.json'),
        'V3-09':('review_software_implemented_independent_human_pilot_pending','reports/v3/Geometry_and_Review.html; research/ifc_citygml_v3/annotations.py'),
        'V3-10':('implemented_measured_profiles_with_declared_limits','results/v3/workflows/index.json'),
        'V3-11':('implemented_building_level_dependency_reuse_and_index','results/v3/index_scaling.json; research/ifc_citygml_v3/incremental.py'),
        'V3-12':('implemented_five_revision_rebuild_checks_pass','results/v3/workflows/index.json'),
        'V3-13':('synthetic_fixed_hazard_sensitivity_implemented_local_reference_gate_unmet','results/v3/workflows/urban_sensitivity.json'),
        'V3-14':('fresh_analytic_holdout_completed_external_qualification_failed','results/v3/holdout/index.json; results/v3/external/index.json'),
        'V3-15':('implementation_report_figures_and_viewer_delivered_manuscript_not_submission_ready','reports/v3/Research_Report.html'),
        'V3-16':('withheld_due_to_qualification_failures','reports/v3/Results_Summary.json')}
    backlog=json.loads((ROOT/'docs/ADVANCED_EXTENSION_V3_BACKLOG.json').read_text())
    for item in backlog['items']:item['execution_status'],item['evidence']=statuses[item['id']]
    backlog.update(status='software_implemented_with_explicit_scope_limits_scientific_qualification_incomplete',report='reports/v3/Research_Report.html',remaining_required_evidence=['Independent semantic review','Verified scan registration and/or suitable Torino survey reference','Disposition of four accepted holdout reference failures and measurement exception','External material-union qualification','Broader novelty comparison and release qualification'])
    (ROOT/'docs/ADVANCED_EXTENSION_V3_EXECUTION.json').write_text(json.dumps(backlog,indent=2),encoding='utf-8')
    print('Built V3 report: 960 main attempts;',test['unique_passed_tests'],'tests; 12 figures; no unsupported qualification claimed')
if __name__=='__main__':main()
